import { describe, it, expect } from '@jest/globals';
import OpenAI from 'openai';

describe('Debug OpenAI Mock', () => {
  it('should check what OpenAI returns', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });
    
    console.log('Client:', client);
    console.log('Chat:', client.chat);
    console.log('Completions:', client.chat?.completions);
    console.log('Create function:', client.chat?.completions?.create);
    
    if (client.chat?.completions?.create) {
      try {
        const response = await client.chat.completions.create({
          model: 'gpt-3.5-turbo',
          messages: [{ role: 'user', content: 'test' }],
        });
        console.log('Response:', response);
      } catch (error) {
        console.log('Error:', error);
      }
    }
    
    expect(true).toBe(true); // Just to make test pass
  });
});